use hec_native_ic::fp::Fp;use std::collections::BTreeMap;
struct Fallible{f:Fp,n:usize,rows:Vec<Option<BTreeMap<usize,u64>>>,dead:bool,rank:usize}
impl Fallible{fn new(n:usize,ell:u64)->Self{Self{f:Fp::new(ell),n,rows:vec![None;n],dead:false,rank:0}}fn k(&self)->Option<u64>{if self.dead{None}else{self.rows[self.n-1].as_ref().map(|r|*r.get(&self.n).unwrap_or(&0))}}fn insert(&mut self,v:&[u64],rhs:u64){if self.dead{return}let mut r:BTreeMap<_,_>=v.iter().copied().chain([rhs]).enumerate().filter(|x|x.1!=0).collect();while let Some((&j,&a))=r.first_key_value(){if j==self.n{self.dead=true;return}if let Some(p)=&self.rows[j]{for(&k,&b)in p{let x=self.f.sub(*r.get(&k).unwrap_or(&0),self.f.mul(a,b));if x==0{r.remove(&k);}else{r.insert(k,x);}}}else{let inv=self.f.inv(a);for x in r.values_mut(){*x=self.f.mul(*x,inv)}self.rows[j]=Some(r);self.rank+=1;return}}}}
struct Dense{f:Fp,n:usize,rows:Vec<Option<Vec<u64>>>,dead:bool,rank:usize}
impl Dense{fn new(n:usize,ell:u64)->Self{Self{f:Fp::new(ell),n,rows:vec![None;n],dead:false,rank:0}}fn k(&self)->Option<u64>{if self.dead{None}else{self.rows[self.n-1].as_ref().map(|r|r[self.n])}}fn insert(&mut self,v:&[u64],rhs:u64){if self.dead{return}let mut r=v.to_vec();r.push(rhs);for j in (0..self.n-1).rev().chain([self.n-1]){let a=r[j];if a==0{continue}if let Some(p)=&self.rows[j]{for k in 0..=self.n{r[k]=self.f.sub(r[k],self.f.mul(a,p[k]));}}else{let inv=self.f.inv(a);for x in &mut r{*x=self.f.mul(*x,inv)}self.rows[j]=Some(r);self.rank+=1;return}}if r[self.n]!=0{self.dead=true}}}
pub struct Pair{s:Fallible,d:Dense}
impl Pair{pub fn new(n:usize,ell:u64)->Self{Self{s:Fallible::new(n,ell),d:Dense::new(n,ell)}}pub fn insert(&mut self,v:&[u64],rhs:u64){self.s.insert(v,rhs);self.d.insert(v,rhs);assert_eq!(self.s.dead,self.d.dead);if !self.s.dead{assert_eq!(self.s.rank,self.d.rank);assert_eq!(self.s.k(),self.d.k())}}pub fn status(&self)->Option<(usize,Option<u64>)>{if self.s.dead{None}else{Some((self.s.rank,self.s.k()))}}}
